43	export const useAppStore = create<AppState>((set) => ({
44	  filters: DEFAULT_FILTERS,
45	  compareIds: [],
46	  setFilter: (key, value) =>
47	    set((s) => ({ filters: { ...s.filters, [key]: value } })),
48	  resetFilters: () => set({ filters: DEFAULT_FILTERS }),
49	  toggleCompare: (id) =>
50	    set((s) => {
51	      if (s.compareIds.includes(id)) {
52	        return { compareIds: s.compareIds.filter((x) => x !== id) };
53	      }
54	      if (s.compareIds.length >= 4) return s;
55	      return { compareIds: [...s.compareIds, id] };
