60	  temp_c: 20,
61	  hvac_on: false,
62	  speed_kph: 100,
63	  preconditioned: {},
64	  setTemp: (c) => set({ temp_c: Math.max(-40, Math.min(40, c)) }),
65	  setHvacOn: (v) => set({ hvac_on: v }),
66	  setSpeed: (v) => set({ speed_kph: Math.max(40, Math.min(130, v)) }),
