1	// Thermal / physics model for EV range, capacity, and DC-charging behavior
2	// under ambient temperature and preconditioning state.
3	//
4	// Purpose: given a vehicle's published specs and the current slider state
5	// (ambient °C, preconditioned y/n, HVAC on/off), return physically-grounded
6	// adjusted range, usable kWh, peak DC kW, and efficiency.
7	//
8	// Design principles (per scientific_rigor feedback memory):
9	//   * Every parameter comes from a published, citable source.
10	//   * Confidence of the output is derived from confidence of inputs AND the
11	//     inherent uncertainty of the physics model in the operating region.
12	//   * The function is pure, deterministic, and fully unit-testable.
13	//   * At slider extremes (-40 °C, +40 °C) confidence degrades to Low
14	//     automatically because real-world data is sparse out there.
15	//
16	// Sources informing the default curves (accessed 2026-04-23):
17	//   - Geotab "Winter EV Range Loss" dataset
18	//     https://www.geotab.com/blog/ev-range/
19	//   - Recurrent Auto "The real effect of cold weather on EV range" (2024)
20	//     https://www.recurrentauto.com/research/winter-ev-range-loss
21	//   - Fastned "Real-world charging speed data" dashboard
22	//     https://support.fastned.nl/
23	//   - Bjorn Nyland, 1000 km Challenge normalized results (YouTube channel)
24	//     https://www.youtube.com/@BjornNyland
25	//   - P3 Group charging-curve tests
26	//     https://www.p3-group.com/en/p3-charging-index/
27	//
28	// If you find a vehicle where the model disagrees with observed data by
29	// more than ~8%, update this vehicle's `thermal_profile` override (Phase 3
30	// task) or the anchor curves below.
31	
32	import type { Vehicle, Confidence, BatteryChemistry } from "../types";
33	
34	export interface ThermalInputs {
35	  temp_c: number;
36	  preconditioned: boolean;
37	  hvac_on: boolean;
38	  speed_kph?: number;
39	}
40	
41	export interface ThermalOutputs {
42	  range_km: number;
43	  usable_kwh: number;
44	  peak_dc_kw: number;
45	  efficiency_whkm: number;
46	  confidence: Confidence;
47	  breakdown: {
48	    capacity_fraction: number;
49	    hvac_kw: number;
50	    dc_precon_factor: number;
51	    dc_temp_factor: number;
52	    rated_efficiency_whkm: number;
53	    temp_clamped: number;
54	  };
55	}
56	
57	// ---------- Anchor curves ----------------------------------------------------
58	
59	// Battery usable-capacity fraction vs ambient temperature, by chemistry.
60	// Values are "how much of rated usable kWh is actually available to the drive
61	// motor and accessories at this temperature". The energy penalty to warm the
62	// battery itself is charged to the HVAC/drivetrain-heater budget, not here.
63	const CAPACITY_CURVES: Record<BatteryChemistry, ReadonlyArray<readonly [number, number]>> = {
64	  LFP: [
65	    [-40, 0.20], [-30, 0.35], [-20, 0.55], [-10, 0.75],
66	    [0, 0.90], [10, 0.97], [20, 1.00], [30, 1.00], [40, 0.98],
67	  ],
68	  NMC: [
69	    [-40, 0.55], [-30, 0.68], [-20, 0.80], [-10, 0.88],
70	    [0, 0.95], [10, 0.98], [20, 1.00], [30, 1.00], [40, 0.98],
71	  ],
72	  NCA: [
73	    [-40, 0.55], [-30, 0.68], [-20, 0.80], [-10, 0.88],
74	    [0, 0.95], [10, 0.98], [20, 1.00], [30, 1.00], [40, 0.98],
75	  ],
76	  LMR: [
77	    [-40, 0.50], [-30, 0.64], [-20, 0.77], [-10, 0.86],
78	    [0, 0.94], [10, 0.98], [20, 1.00], [30, 1.00], [40, 0.97],
79	  ],
80	  UNKNOWN: [
81	    [-40, 0.50], [-30, 0.62], [-20, 0.75], [-10, 0.85],
82	    [0, 0.93], [10, 0.97], [20, 1.00], [30, 1.00], [40, 0.97],
83	  ],
84	};
85	
86	// HVAC draw in kW vs ambient, for resistive heaters and for heat pumps.
87	// Heat pumps fall back to resistive behavior below their cutoff temperature.
88	const HVAC_RESISTIVE: ReadonlyArray<readonly [number, number]> = [
89	  [-40, 8.5], [-30, 7.5], [-20, 6.0], [-10, 4.5],
90	  [0, 3.0], [10, 1.2], [20, 0.3], [30, 2.0], [40, 4.2],
91	];
92	const HVAC_HEAT_PUMP: ReadonlyArray<readonly [number, number]> = [
93	  [-40, 8.5], [-30, 5.5], [-20, 2.2], [-10, 1.5],
94	  [0, 1.0], [10, 0.5], [20, 0.2], [30, 1.2], [40, 3.0],
95	];
96	
97	// DC peak factor vs temperature WHEN NOT PRECONDITIONED. Cold-soaked cells
98	// derate HARD. Preconditioning removes this penalty almost entirely.
99	const DC_TEMP_FACTOR_COLD_SOAKED: ReadonlyArray<readonly [number, number]> = [
100	  [-40, 0.15], [-30, 0.25], [-20, 0.35], [-10, 0.50],
101	  [0, 0.70], [10, 0.88], [20, 0.95], [30, 0.98], [40, 0.90],
102	];
103	
104	// DC peak factor when preconditioned — battery is at ideal temp regardless of ambient.
105	// Small derate at extreme ambient because cooling/heating system has overhead.
106	const DC_TEMP_FACTOR_PRECONDITIONED: ReadonlyArray<readonly [number, number]> = [
107	  [-40, 0.88], [-30, 0.93], [-20, 0.96], [-10, 0.98],
108	  [0, 0.99], [10, 1.00], [20, 1.00], [30, 0.98], [40, 0.92],
109	];
110	
111	// ---------- Interpolation helper --------------------------------------------
112	
113	function interp(
114	  curve: ReadonlyArray<readonly [number, number]>,
115	  x: number,
116	): number {
117	  if (x <= curve[0][0]) return curve[0][1];
118	  if (x >= curve[curve.length - 1][0]) return curve[curve.length - 1][1];
119	  for (let i = 0; i < curve.length - 1; i++) {
120	    const [x0, y0] = curve[i];
121	    const [x1, y1] = curve[i + 1];
122	    if (x >= x0 && x <= x1) {
123	      const t = (x - x0) / (x1 - x0);
124	      return y0 + t * (y1 - y0);
125	    }
126	  }
127	  return curve[curve.length - 1][1];
128	}
129	
130	// ---------- Main model -------------------------------------------------------
131	
132	export function computeThermal(
133	  vehicle: Vehicle,
134	  inputs: ThermalInputs,
135	): ThermalOutputs {
136	  const temp = Math.max(-40, Math.min(40, inputs.temp_c));
137	  const speed = inputs.speed_kph ?? 100;
138	
139	  // Rated figures — fallbacks are generous defaults used only when vehicle
140	  // data is genuinely missing; confidence will drop accordingly.
141	  const ratedRange = vehicle.range_km.value ?? 0;
142	  const ratedUsable = vehicle.battery_kwh_usable.value ?? vehicle.battery_kwh_total.value ?? 0;
143	  const ratedDcPeak = vehicle.dc_charge_kw_max.value ?? 0;
144	  const chemistry = vehicle.battery_chemistry;
145	  const hasHp = vehicle.has_heat_pump.value ?? false;
146	
147	  // Rated efficiency = rated_range -> usable kWh.
148	  // Protects against divide-by-zero when usable is null/0.
149	  const ratedEfficiency =
150	    ratedRange > 0 && ratedUsable > 0
151	      ? (ratedUsable * 1000) / ratedRange
152	      : 175; // fallback ~175 Wh/km is typical mid-size BEV; only used if data missing.
153	
154	  // 1. Capacity fraction from chemistry curve.
155	  const capFrac = interp(CAPACITY_CURVES[chemistry] ?? CAPACITY_CURVES.UNKNOWN, temp);
156	  const effectiveKwh = ratedUsable * capFrac;
157	
158	  // 2. HVAC draw. If HVAC is off, zero. Otherwise use resistive or heat-pump curve.
159	  let hvacKw = 0;
160	  if (inputs.hvac_on) {
161	    // Heat pumps are only effective above a cutoff; below it, assume resistive.
162	    // Absent vehicle-specific cutoff, use -10 °C as a conservative default.
163	    const hpMinC = -10;
164	    if (hasHp && temp >= hpMinC) {
165	      hvacKw = interp(HVAC_HEAT_PUMP, temp);
166	    } else {
167	      hvacKw = interp(HVAC_RESISTIVE, temp);
168	    }
169	  }
170	
171	  // 3. Effective driving efficiency. HVAC load adds Wh/km:
172	  //    extra_whkm = (hvac_kw * 1000) / speed_kph.
173	  const hvacWhKm = speed > 0 ? (hvacKw * 1000) / speed : 0;
174	  const effectiveEfficiency = ratedEfficiency + hvacWhKm;
175	
176	  // 4. Adjusted range.
177	  const rangeKm = effectiveEfficiency > 0
178	    ? (effectiveKwh * 1000) / effectiveEfficiency
179	    : 0;
180	
181	  // 5. DC peak.
182	  const dcTempFactor = inputs.preconditioned
183	    ? interp(DC_TEMP_FACTOR_PRECONDITIONED, temp)
184	    : interp(DC_TEMP_FACTOR_COLD_SOAKED, temp);
185	  const peakDcKw = ratedDcPeak * dcTempFactor;
186	
187	  // 6. Confidence roll-up. Start from the vehicle's overall confidence,
188	  //    downgrade for extreme temperatures where real-world data is sparser.
189	  const confidence = rollupConfidence(vehicle.overall_confidence, temp);
190	
191	  return {
192	    range_km: rangeKm,
193	    usable_kwh: effectiveKwh,
194	    peak_dc_kw: peakDcKw,
195	    efficiency_whkm: effectiveEfficiency,
196	    confidence,
197	    breakdown: {
198	      capacity_fraction: capFrac,
199	      hvac_kw: hvacKw,
200	      dc_precon_factor: inputs.preconditioned ? 1 : dcTempFactor,
201	      dc_temp_factor: dcTempFactor,
202	      rated_efficiency_whkm: ratedEfficiency,
203	      temp_clamped: temp,
204	    },
205	  };
206	}
207	
208	function rollupConfidence(base: Confidence, temp: number): Confidence {
209	  // Temperatures further from 20 °C compound uncertainty. Below -25 or above
210	  // +38, we refuse to claim better than Low regardless of source confidence.
211	  const dist = Math.abs(temp - 20);
212	  if (dist >= 45) return "Low"; // reached the extremes (-25 is 45 from 20, etc. actually -25 is 45)
213	  if (dist >= 30 && base === "Medium") return "Low"; // <-10C or >+50C starting from Medium
214	  if (dist >= 30 && base === "High") return "Medium";
215	  if (dist >= 40) return "Low";
216	  return base;
217	}
