1	// Sanity-check the thermal model against physical expectations.
2	// Run with: npx tsx src/lib/thermal.test.ts    (requires `npm i -D tsx`)
3	//
4	// These are assertions, not a real framework, to keep dependencies minimal.
5	
6	import { computeThermal } from "./thermal";
7	import type { Vehicle } from "../types";
8	
9	const FIXTURE: Vehicle = {
10	  id: "fixture",
11	  brand_id: "test",
12	  model: "Fixture",
13	  generation_label: "v1",
14	  year_start: 2025,
15	  year_end: null,
16	  powertrain: "BEV",
17	  body_style: "Sedan",
18	  drivetrain_variant: "AWD",
19	  trim_label: "Long Range AWD",
20	  battery_kwh_total: { value: 80, confidence: "High" },
21	  battery_kwh_usable: { value: 75, confidence: "High" },
22	  battery_chemistry: "NMC",
23	  range_km: { value: 500, confidence: "High" },
24	  range_protocol: "EPA",
25	  ac_charge_kw_max: { value: 11, confidence: "High" },
26	  dc_charge_kw_max: { value: 250, confidence: "High" },
27	  port_type: "NACS",
28	  seats: 5,
29	  cargo_l_seats_up: null,
30	  cargo_l_seats_down: null,
31	  tow_rating_kg: null,
32	  weight_kg: null,
33	  has_heat_pump: { value: true, confidence: "High" },
34	  thermal_management: "active_liquid",
35	  charging_curve_20c: [],
36	  msrp_cad: { value: 70000, confidence: "High" },
37	  federal_izev_cad: { value: 0, confidence: "High" },
38	  provincial_rebate_cad_on: { value: 0, confidence: "High" },
39	  overall_confidence: "High",
40	};
41	
42	function assertNear(actual: number, expected: number, tol: number, label: string) {
43	  const diff = Math.abs(actual - expected);
44	  if (diff > tol) {
45	    throw new Error(`${label}: expected ~${expected} ±${tol}, got ${actual.toFixed(2)}`);
46	  }
47	}
48	
49	function assertLess(actual: number, bound: number, label: string) {
50	  if (actual >= bound) throw new Error(`${label}: expected <${bound}, got ${actual.toFixed(2)}`);
51	}
52	
53	// Baseline: at 20 °C, HVAC off, preconditioned — should match rated specs closely.
54	const base = computeThermal(FIXTURE, { temp_c: 20, preconditioned: true, hvac_on: false });
55	assertNear(base.range_km, 500, 5, "20C baseline range");
56	assertNear(base.peak_dc_kw, 250, 5, "20C baseline DC peak");
57	assertNear(base.usable_kwh, 75, 0.5, "20C baseline usable kWh");
58	
59	// Winter cold-soaked -20C, HVAC on, heat pump: range should drop substantially, DC peak massively.
60	const winter = computeThermal(FIXTURE, { temp_c: -20, preconditioned: false, hvac_on: true });
61	assertLess(winter.range_km, 380, "-20C non-precon range should be <380");
62	assertLess(winter.peak_dc_kw, 100, "-20C non-precon DC peak should be <100 kW");
63	
64	// Same cold, but preconditioned + no HVAC -> DC peak recovers, range still dented by battery capacity.
65	const winterPrecon = computeThermal(FIXTURE, { temp_c: -20, preconditioned: true, hvac_on: false });
66	if (winterPrecon.peak_dc_kw <= winter.peak_dc_kw) {
67	  throw new Error("Preconditioning should raise DC peak vs cold-soaked");
68	}
69	if (winterPrecon.range_km <= winter.range_km) {
70	  throw new Error("HVAC-off should improve range vs HVAC-on");
71	}
72	
73	// Hot day: +35C, HVAC on. Range should derate modestly; DC peak should derate some.
74	const summer = computeThermal(FIXTURE, { temp_c: 35, preconditioned: true, hvac_on: true });
75	if (summer.range_km >= base.range_km) throw new Error("Hot + HVAC should be worse than 20C idle");
76	if (summer.peak_dc_kw >= base.peak_dc_kw + 1) throw new Error("Hot DC peak should not exceed 20C");
77	
78	// Confidence should downgrade at extremes.
79	const extreme = computeThermal(FIXTURE, { temp_c: -35, preconditioned: false, hvac_on: true });
80	if (extreme.confidence === "High") throw new Error("Confidence should downgrade at -35C");
81	
82	console.log("✓ thermal.test.ts — all assertions pass");
83	console.log("  baseline (20C):", base.range_km.toFixed(0), "km,", base.peak_dc_kw.toFixed(0), "kW");
84	console.log("  winter cold-soaked (-20C, HVAC on):", winter.range_km.toFixed(0), "km,", winter.peak_dc_kw.toFixed(0), "kW");
85	console.log("  winter precon (-20C, HVAC off):", winterPrecon.range_km.toFixed(0), "km,", winterPrecon.peak_dc_kw.toFixed(0), "kW");
86	console.log("  summer (35C, HVAC on):", summer.range_km.toFixed(0), "km,", summer.peak_dc_kw.toFixed(0), "kW");
