2	import type { ThermalOutputs } from "../lib/thermal";
3	
4	// Pure-SVG chart — no external dependency. Shows each vehicle's DC charging
5	// curve (kW vs SoC%). Curves scale DOWN by the current thermal_factor so the
6	// chart LIVE-UPDATES with the slider: preconditioned = near-rated, cold-soaked
7	// = flattened. The flat curve at extreme cold is the most visceral demo in the
8	// whole app.
9	
10	const COLORS = [
11	  "#2a7cff", // accent-blue
12	  "#1fb76b", // accent-green
13	  "#f6a72a", // accent-amber
14	  "#e8453c", // accent-red
15	] as const;
16	
17	const W = 720;
18	const H = 320;
19	const PAD_LEFT = 48;
20	const PAD_RIGHT = 24;
21	const PAD_TOP = 16;
22	const PAD_BOTTOM = 40;
23	const PLOT_W = W - PAD_LEFT - PAD_RIGHT;
24	const PLOT_H = H - PAD_TOP - PAD_BOTTOM;
25	
26	function xForSoc(soc: number): number {
27	  return PAD_LEFT + (soc / 100) * PLOT_W;
28	}
29	
30	function yForKw(kw: number, maxKw: number): number {
31	  return PAD_TOP + PLOT_H - (kw / maxKw) * PLOT_H;
32	}
33	
34	export function ChargingCurveChart({
35	  vehicles,
36	  thermals,
37	}: {
38	  vehicles: Vehicle[];
39	  thermals: Record<string, ThermalOutputs>;
40	}) {
41	  // Build per-vehicle scaled curves.
42	  const scaledCurves = vehicles.map((v, i) => {
43	    const thermal = thermals[v.id];
44	    const factor = thermal?.breakdown.dc_temp_factor ?? 1;
45	    const points = v.charging_curve_20c.map((p) => ({
46	      soc: p.soc_pct,
47	      kw: p.kw * factor,
48	    }));
49	    return { vehicle: v, points, color: COLORS[i % COLORS.length] };
50	  });
51	
52	  // Determine Y-axis max from the largest rated peak (not the scaled one) so
53	  // the axis stays steady as the slider moves — easier to read.
54	  const maxKw = Math.max(
55	    100,
56	    ...vehicles.map((v) => v.dc_charge_kw_max.value ?? 100),
57	  );
58	
59	  // Rounded Y ticks.
60	  const yTickCount = 5;
61	  const yTicks = Array.from({ length: yTickCount + 1 }, (_, i) =>
62	    Math.round((maxKw / yTickCount) * i),
63	  );
64	
65	  const xTicks = [0, 20, 40, 60, 80, 100];
66	
67	  return (
68	    <div className="bg-ink-800 rounded-lg border border-ink-700 p-4 mb-6">
69	      <div className="flex items-baseline gap-4 mb-2">
70	        <h3 className="font-display text-sm uppercase tracking-widest text-ink-300">
71	          DC charging curves
72	        </h3>
73	        <span className="text-xs text-ink-500">
74	          kW vs state-of-charge · scales with the conditions slider above
75	        </span>
76	      </div>
77	
78	      <svg
79	        viewBox={`0 0 ${W} ${H}`}
80	        width="100%"
81	        className="block"
82	        preserveAspectRatio="xMidYMid meet"
83	      >
84	        {/* Y grid + labels */}
85	        {yTicks.map((t) => {
86	          const y = yForKw(t, maxKw);
87	          return (
88	            <g key={`y${t}`}>
89	              <line
90	                x1={PAD_LEFT}
91	                x2={W - PAD_RIGHT}
92	                y1={y}
93	                y2={y}
94	                stroke="#26262d"
95	                strokeWidth={1}
96	              />
97	              <text
98	                x={PAD_LEFT - 6}
99	                y={y + 4}
100	                textAnchor="end"
101	                fontSize="10"
102	                fill="#6b6b78"
103	                fontFamily="ui-monospace, SF Mono, monospace"
104	              >
105	                {t}
106	              </text>
107	            </g>
108	          );
109	        })}
110	
111	        {/* X grid + labels */}
112	        {xTicks.map((t) => {
113	          const x = xForSoc(t);
114	          return (
115	            <g key={`x${t}`}>
116	              <line
117	                x1={x}
118	                x2={x}
119	                y1={PAD_TOP}
120	                y2={PAD_TOP + PLOT_H}
121	                stroke="#26262d"
122	                strokeWidth={1}
123	              />
124	              <text
125	                x={x}
126	                y={PAD_TOP + PLOT_H + 14}
127	                textAnchor="middle"
128	                fontSize="10"
129	                fill="#6b6b78"
130	                fontFamily="ui-monospace, SF Mono, monospace"
131	              >
132	                {t}%
133	              </text>
134	            </g>
135	          );
136	        })}
137	
138	        {/* Axis labels */}
139	        <text
140	          x={PAD_LEFT - 30}
141	          y={PAD_TOP + PLOT_H / 2}
142	          textAnchor="middle"
143	          transform={`rotate(-90 ${PAD_LEFT - 30} ${PAD_TOP + PLOT_H / 2})`}
144	          fontSize="10"
145	          fill="#a0a0ac"
146	        >
147	          kW
148	        </text>
149	        <text
150	          x={PAD_LEFT + PLOT_W / 2}
151	          y={H - 6}
152	          textAnchor="middle"
153	          fontSize="10"
154	          fill="#a0a0ac"
155	        >
156	          state of charge
157	        </text>
158	
159	        {/* Curves */}
160	        {scaledCurves.map(({ vehicle, points, color }) => {
161	          if (points.length === 0) return null;
162	          const d = points
163	            .map((p, idx) => {
164	              const x = xForSoc(p.soc);
165	              const y = yForKw(p.kw, maxKw);
166	              return `${idx === 0 ? "M" : "L"}${x.toFixed(1)},${y.toFixed(1)}`;
167	            })
168	            .join(" ");
169	          return (
170	            <g key={vehicle.id}>
171	              <path d={d} fill="none" stroke={color} strokeWidth={2} />
172	              {points.map((p, idx) => (
173	                <circle
174	                  key={idx}
175	                  cx={xForSoc(p.soc)}
176	                  cy={yForKw(p.kw, maxKw)}
177	                  r={3}
178	                  fill={color}
179	                />
180	              ))}
181	            </g>
182	          );
183	        })}
184	      </svg>
185	
186	      {/* Legend */}
187	      <div className="flex flex-wrap gap-x-6 gap-y-1 mt-2">
188	        {scaledCurves.map(({ vehicle, color }) => {
189	          const thermal = thermals[vehicle.id];
190	          const peakAdjusted = thermal?.peak_dc_kw ?? vehicle.dc_charge_kw_max.value ?? 0;
191	          const peakRated = vehicle.dc_charge_kw_max.value ?? 0;
192	          const diff = peakRated > 0 ? Math.round((peakAdjusted / peakRated) * 100) : 100;
193	          return (
194	            <div key={vehicle.id} className="flex items-center gap-2 text-xs">
195	              <span
196	                className="inline-block w-3 h-3 rounded-sm"
197	                style={{ backgroundColor: color }}
198	              />
199	              <span className="text-ink-200">
200	                {vehicle.model}{" "}
201	                <span className="text-ink-400">{vehicle.trim_label}</span>
202	              </span>
203	              <span className="text-ink-500 font-mono">
204	                {Math.round(peakAdjusted)} kW peak{" "}
205	                <span className="text-ink-600">({diff}% of rated)</span>
206	              </span>
207	            </div>
208	          );
209	        })}
210	      </div>
211	
212	      {vehicles.some((v) => v.charging_curve_20c.length === 0) && (
213	        <div className="mt-2 text-[11px] text-ink-500">
214	          Some vehicles don't yet have charging-curve data in the seed; they'll appear once added.
215	        </div>
216	      )}
217	    </div>
218	  );
219	}
